7	/**
8	 * Components are insured at a flat rate and carry no item-specific risk:
9	 * a rune has neither an enchantment level nor a material to be cursed.
10	 */
11	function priceComponents(components: readonly Item[]): ItemPricing {
12	  return {
13	    basePremium: componentsBasePremium(components),
14	    riskSurcharges: 0,
15	  };
16	}
17	
18	/**
19	 * Each item is priced by the pricing policy that governs its kind:
20	 * components may form blocks, main items follow the price list.
21	 */
22	export function priceItems(items: readonly Item[]): ItemPricing {
23	  return combinedPricing(
24	    priceMainItems(items.filter((item) => !isComponent(item))),
25	    priceComponents(items.filter(isComponent)),
26	  );
27	}
