1	import type { Item } from "./policy.js";
2	import type { ItemPricing } from "./premium-contribution.js";
3	import { NO_PRICING, combinedPricing } from "./premium-contribution.js";
4	import { riskSurchargeOf } from "./risk-surcharge.js";
5	
6	/** The MHPCO price list for main items: base premium in G per item type. */
7	const MAIN_ITEM_BASE_PREMIUMS: Readonly<Record<string, number>> = {
8	  sword: 100,
9	  amulet: 60,
10	  staff: 80,
11	  potion: 40,
12	};
13	
14	function mainItemBasePremiumOf(item: Item): number {
15	  return MAIN_ITEM_BASE_PREMIUMS[item.type] ?? 0;
16	}
17	
18	/**
19	 * What one main item contributes: the price list's base premium, and the
20	 * item's own risk surcharges, which scale that same base premium.
21	 */
22	function priceMainItem(item: Item): ItemPricing {
23	  const basePremium = mainItemBasePremiumOf(item);
24	  return {
25	    basePremium,
26	    riskSurcharges: riskSurchargeOf(item, basePremium),
27	  };
28	}
29	
30	export function priceMainItems(mainItems: readonly Item[]): ItemPricing {
31	  return mainItems.reduce<ItemPricing>(
32	    (total, item) => combinedPricing(total, priceMainItem(item)),
33	    NO_PRICING,
34	  );
35	}
