import type { Item } from "./policy.js";
import type { ItemPricing } from "./premium-contribution.js";
import { NO_PRICING, combinedPricing } from "./premium-contribution.js";
import { riskSurchargeOf } from "./risk-surcharge.js";

/** One row of the MHPCO price list: what the office charges for an item type. */
interface PriceListEntry {
  readonly basePremium: number;
}

/**
 * The MHPCO price list for main items. The office states each type's terms as
 * one row, so everything it charges for a sword is read and changed together.
 */
const MAIN_ITEM_PRICE_LIST: Readonly<Record<string, PriceListEntry>> = {
  sword: { basePremium: 100 },
  amulet: { basePremium: 60 },
  staff: { basePremium: 80 },
  potion: { basePremium: 40 },
};

/** An item type absent from the price list is not yet insurable for any amount. */
const NOT_ON_PRICE_LIST: PriceListEntry = { basePremium: 0 };

function priceListEntryOf(item: Item): PriceListEntry {
  return MAIN_ITEM_PRICE_LIST[item.type] ?? NOT_ON_PRICE_LIST;
}

/**
 * What one main item contributes: the price list's base premium, and the
 * item's own risk surcharges, which scale that same base premium.
 */
function priceMainItem(item: Item): ItemPricing {
  const { basePremium } = priceListEntryOf(item);
  return {
    basePremium,
    riskSurcharges: riskSurchargeOf(item, basePremium),
  };
}

export function priceMainItems(mainItems: readonly Item[]): ItemPricing {
  return mainItems.reduce<ItemPricing>(
    (total, item) => combinedPricing(total, priceMainItem(item)),
    NO_PRICING,
  );
}

