import { componentsBasePremium, isComponent } from "./component-block.js";
import { priceMainItems } from "./main-item.js";
import type { Item } from "./policy.js";
import type { ItemPricing } from "./premium-contribution.js";
import { combinedPricing } from "./premium-contribution.js";

/**
 * Components are insured at a flat rate and carry no item-specific risk:
 * a rune has neither an enchantment level nor a material to be cursed.
 */
function priceComponents(components: readonly Item[]): ItemPricing {
  return {
    basePremium: componentsBasePremium(components),
    riskSurcharges: 0,
  };
}

/** The MHPCO sorts what a policy covers into the kinds it prices separately. */
interface ItemsByKind {
  readonly mainItems: readonly Item[];
  readonly components: readonly Item[];
}

function sortByKind(items: readonly Item[]): ItemsByKind {
  const mainItems: Item[] = [];
  const components: Item[] = [];
  for (const item of items) {
    (isComponent(item) ? components : mainItems).push(item);
  }
  return { mainItems, components };
}

/**
 * Each item is priced by the pricing policy that governs its kind:
 * components may form blocks, main items follow the price list.
 */
export function priceItems(items: readonly Item[]): ItemPricing {
  const { mainItems, components } = sortByKind(items);
  return combinedPricing(priceMainItems(mainItems), priceComponents(components));
}

